cudaError_t cudaGetDriverEntryPoint(const char * symbol, void ** funcPtr, unsigned long long flags, cudaDriverEntryPointQueryResult * driverStatus) {
    // TraceCall("cudaGetDriverEntryPoint");
    if (!initialize() || g_interface.hggcGetDriverEntryPoint_ptr == NULL) {
        fprintf(stderr, "Initialize HGGC Api Failed: hggcGetDriverEntryPoint.\n");
        exit(1);
    }

#define MAX_SYMBOL_SIZE 128
    char new_symbol[MAX_SYMBOL_SIZE] = {0};

    const char *old_patterns[] = {"cuuint32_t", "cuuint64_t", "NvSci", "cuda", "CUDA", "cu", "CU"};
    const char *new_patterns[] = {"uint32_t", "uint64_t", "HgSci", "hggc", "HGGC", "hg", "HG"};
    const int rule_count = 7;

    size_t src_idx = 0;
    size_t dst_idx = 0;

    while (symbol[src_idx] != '\0') {
      bool matched = false;
      for (int i = 0; i < rule_count; i++) {
        size_t old_len = strlen(old_patterns[i]);
        size_t new_len = strlen(new_patterns[i]);
        if (strncmp(&symbol[src_idx], old_patterns[i], old_len) == 0) {
          bool hit = false;
          char c1 = old_patterns[i][0];
          char c2 = old_patterns[i][old_len - 1];
          if (src_idx == 0) {
            char after_c2 = symbol[src_idx + old_len];
            hit = (!!isupper(c2) != !!isupper(after_c2));
          } else if (src_idx == (strlen(symbol) - old_len)) {
            char before_c1 = symbol[src_idx - 1];
            hit = (!!isupper(c1) != !!isupper(before_c1));
          } else {
            char before_c1 = symbol[src_idx - 1];
            char after_c2 = symbol[src_idx + old_len];
            bool opposite1 = (!!isupper(c1) != !!isupper(before_c1));
            bool opposite2 = (!!isupper(c2) != !!isupper(after_c2));
            hit = opposite1 && opposite2;
          }
          if ((dst_idx + new_len < MAX_SYMBOL_SIZE) && hit) {
            memcpy(&new_symbol[dst_idx], new_patterns[i], new_len);
            dst_idx += new_len;
            src_idx += old_len;
            matched = true;
            break;
          }
        }
      }
      if (!matched) {
        if (dst_idx + 1 < MAX_SYMBOL_SIZE) {
          new_symbol[dst_idx++] = symbol[src_idx++];
        } else {
          break;
        }
      }
    }

    new_symbol[dst_idx] = '\0';

    bool needProfile = g_profileHandler.isCallbackEnabled != NULL &&
        g_profileHandler.isCallbackEnabled(g_profileDomain, cudart_TRACE_CBID_cudaGetDriverEntryPoint) != 0;
    if (needProfile) {
        g_profileHandler.profileCallbackBegin(g_profileDomain, cudart_TRACE_CBID_cudaGetDriverEntryPoint);
    }

    auto __ret = g_interface.hggcGetDriverEntryPoint_ptr((const char * )new_symbol, (void ** )funcPtr, (unsigned long long)flags, (hggcDriverEntryPointQueryResult * )driverStatus);

    if (needProfile) {
        g_profileHandler.profileCallbackEnd(g_profileDomain, cudart_TRACE_CBID_cudaGetDriverEntryPoint);
    }

    return (cudaError_t)__ret;
}

