cudaError_t cudaRuntimeGetVersion(int * runtimeVersion) {
    // TraceCall("cudaRuntimeGetVersion");
    cudaError_t res = cudaSuccess;

    if (!runtimeVersion) {
        res = cudaErrorInvalidValue;
    }

    if (res == cudaSuccess) {
        *runtimeVersion = CUDART_VERSION;
    }

    return res;
}

